import fs from 'node:fs/promises'
import path from 'node:path'

export async function ensureDir(dirPath: string): Promise<void> {
  await fs.mkdir(dirPath, { recursive: true })
}

export async function pathExists(filePath: string): Promise<boolean> {
  try {
    await fs.access(filePath)
    return true
  } catch {
    return false
  }
}

export async function readJsonFile<T>(filePath: string): Promise<T | null> {
  try {
    const raw = await fs.readFile(filePath, 'utf8')
    return JSON.parse(raw) as T
  } catch (error) {
    if ((error as NodeJS.ErrnoException).code === 'ENOENT') {
      return null
    }
    throw error
  }
}

export async function writeJsonFileAtomic(filePath: string, value: unknown): Promise<void> {
  const directory = path.dirname(filePath)
  await ensureDir(directory)
  const tempPath = path.join(directory, `${path.basename(filePath)}.${process.pid}.${Date.now()}.tmp`)
  await fs.writeFile(tempPath, JSON.stringify(value, null, 2) + '\n', 'utf8')
  await fs.rename(tempPath, filePath)
}

export async function withFileLock<T>(
  lockPath: string,
  work: () => Promise<T>,
): Promise<T> {
  await ensureDir(path.dirname(lockPath))
  const payload = JSON.stringify({ pid: process.pid, acquiredAt: new Date().toISOString() })

  async function acquire(): Promise<void> {
    try {
      await fs.writeFile(lockPath, payload, { flag: 'wx' })
      return
    } catch (error) {
      const code = (error as NodeJS.ErrnoException).code
      if (code !== 'EEXIST') {
        throw error
      }

      const stalePayload = await readJsonFile<{ pid?: number }>(lockPath)
      const stalePid = stalePayload?.pid
      if (!stalePid) {
        await fs.rm(lockPath, { force: true })
        await fs.writeFile(lockPath, payload, { flag: 'wx' })
        return
      }

      try {
        process.kill(stalePid, 0)
      } catch (killError) {
        const killCode = (killError as NodeJS.ErrnoException).code
        if (killCode === 'ESRCH') {
          await fs.rm(lockPath, { force: true })
          await fs.writeFile(lockPath, payload, { flag: 'wx' })
          return
        }
      }

      throw new Error(`State lock is already held: ${lockPath}`)
    }
  }

  await acquire()
  try {
    return await work()
  } finally {
    await fs.rm(lockPath, { force: true })
  }
}
